function runTest(){stopTest();let c=effectiveTestConfig();if(!isTutorial()&&(c.spawnMode==="random"||c.spawnMode==="battle"||c.boardShape==="random"||c.boardSizeKey==="random")){state.testRollSeed=freshSeed();c=effectiveTestConfig();}const def=resolvedTestBoard(c),program=deepClone(state.draft.blocks),players=[{id:"me",name:"あなた",color:"blue",program}];if(c.npc)players.push({id:"test-npc",name:`NPC・${testNpcLabel(c.npcType)}`,color:"red",program:makeTestNpcProgram(c.mode,c.npcType,0)});const spawns=testSpawns(c,players.length,def);if(c.spawnMode==="fixed"&&!spawns){updateTestBenchUI();return toast("指定スポーンを全員分設定してください");}let game;try{game=createGameState({mode:c.mode,seed:isTutorial()?"tutorial-test-v5":state.testRollSeed,size:def.size,boardShape:def.shape,boardSizeKey:def.sizeKey,maxTicks:Number.MAX_SAFE_INTEGER,stagnationTicks:Number.MAX_SAFE_INTEGER,allowSolo:!c.npc,players,spawns});}catch(e){console.error(e);return toast("スポーン位置を確認してください");}state.testGame=game;renderBoard($("#testBoard"),game);$("#testBoardMeta").textContent=`${game.size} × ${game.size} ・ ${boardChoiceLabel(game.boardShape,game.boardSizeKey)}`;$("#testStatus").textContent=`実行中 ・ ${MODE_LABELS[c.mode]} ・ ${c.npc?testNpcLabel(c.npcType):"NPCなし"}`;const step=Number(state.profile?.tutorialStep||0);let halted=0;state.testTimer=setInterval(()=>{const prev=game.board?.map(r=>[...r]);stepGame(game);renderBoard($("#testBoard"),game,prev);const a=game.agents[0],stopped=a?.alive&&a.vm?.halted===true&&(c.mode==="territory"||c.mode==="splat");halted=stopped?halted+1:0;if(isTutorial()&&step===10&&a.alive&&game.tick>=30){stopTest();state.tutorialFinalPassed=true;$("#testStatus").textContent="成功：崖を判断して走り続けられました。駒を保存してください。";renderTutorial();return;}if(!a?.alive||game.finished||halted>=2){const reason=!a?.alive?(a.deathReason==="cliff"?"崖から落ちました":"ゲームオーバー"):halted>=2?"コードの末尾まで実行して停止しました":game.finishReason||"ゲーム終了";stopTest(`テスト終了：${reason}（${game.tick}tick）`);if(isTutorial()&&step===2&&halted>=2&&game.tick<=4)tutorialProgress(3);else if(isTutorial()&&step===4&&!a.alive&&a.deathReason==="cliff")tutorialProgress(5);}},120);}
