function requestUnsavedAction(action){if(state.view!=="editor"||!isDraftDirty()){action();return;}document.querySelectorAll(".unsaved-code-overlay").forEach(n=>n.remove());const o=document.createElement("div");o.className="expression-overlay info-overlay unsaved-code-overlay";o.innerHTML=`<div class="expression-card info-card unsaved-code-card"><small>未保存のコードがあります</small><h3>コードを保存しますか？</h3><p>コードの保存が出来ていません。<br>このページから移動してもよろしいですか？</p><div class="unsaved-code-actions"><button class="primary-button" type="button" data-save-move>保存して移動</button><button class="secondary-button" type="button" data-discard-move>保存せず移動</button><button class="text-button" type="button" data-cancel-move>キャンセル</button></div></div>`;o.querySelector("[data-save-move]").onclick=async()=>{o.remove();if(state.draft.programId)await overwriteDraft(action);else openNamedSave(false,action);};o.querySelector("[data-discard-move]").onclick=()=>{o.remove();discardDraftChanges();action();};o.querySelector("[data-cancel-move]").onclick=()=>o.remove();o.onclick=e=>{if(e.target===o)o.remove();};document.body.append(o);}


async function saveMatchRecord(game,results,{online=false,seriesId="",roundIndex=0,totalRounds=1}={}){
  if(!state.user?.userTrackingId)return null;
  if(online&&state.currentOnlineMeta?.saveOwnerId&&state.currentOnlineMeta.saveOwnerId!==state.user.userTrackingId)return null;
  const participants=game.agents.map(a=>({userTrackingId:a.userTrackingId||"",username:a.name,color:a.color}));
  const programs=game.agents.map(a=>({id:a.id,userTrackingId:a.userTrackingId||"",name:a.name,color:a.color,programName:a.programName||"",program:a.program}));
  try{
    const saved=await api("/api/now-coding/matches",{method:"POST",body:JSON.stringify({
      userTrackingId:state.user.userTrackingId,mode:game.mode,seed:game.seed,
      settings:{size:game.size,boardShape:game.boardShape||"square",boardSizeKey:game.boardSizeKey||"custom",playableCount:game.playableCount||game.size*game.size,playerCount:game.agents.length,maxTicks:game.maxTicks,online,seriesId,roundIndex,totalRounds},
      participants,results,programs,spawn:game.spawns||[],durationTicks:game.tick,finishReason:game.finishReason,ruleVersion:game.ruleVersion||"now-coding-v3"
    })});
    state.matches.unshift({matchId:saved.matchId,replayId:saved.replayId,mode:game.mode,seed:game.seed,settings:{size:game.size,boardShape:game.boardShape||"square",boardSizeKey:game.boardSizeKey||"custom",seriesId,roundIndex,totalRounds},results,createdAt:new Date().toISOString()});
    renderHome();return saved;
  }catch(error){console.warn("match save failed",error);toast("対戦記録の保存に失敗しました");return null;}
}
async function replayMatch(replayId){
  if(!replayId||!state.user)return;
  try{
    const d=await api(`/api/now-coding/replays/${encodeURIComponent(replayId)}?userTrackingId=${encodeURIComponent(state.user.userTrackingId)}`);
    const r=d.replay;const players=(r.programs||[]).map((p,i)=>({id:p.id||`p${i}`,userTrackingId:p.userTrackingId||"",name:p.name||`駒${i+1}`,color:p.color||PLAYER_COLORS[i],program:p.program||[]}));
    state.series=null;state.onlineSeries=null;state.currentOnlineMeta=null;showView("battle",true);startBattle({mode:r.mode||"territory",seed:r.seed,size:Number(r.settings?.size||21),boardShape:r.settings?.boardShape||null,boardSizeKey:r.settings?.boardSizeKey||null,players,spawns:r.spawn||null,maxTicks:Number(r.settings?.maxTicks||600)},true);
  }catch(error){console.error(error);toast("リプレイを読み込めませんでした");}
}
