function toggleMode(mode,online=false){const set=online?state.onlineModes:state.selectedModes;if(set.has(mode)&&set.size>1)set.delete(mode);else set.add(mode);if(online)state.onlineFocusedMode=mode;else state.focusedMode=mode;renderModeRail(online);}
function renderModeRail(online=false){const set=online?state.onlineModes:state.selectedModes,focus=online?state.onlineFocusedMode:state.focusedMode,attr=online?"data-online-mode":"data-mode",rail=online?"#onlineModeRail":"#modeRail";$$( `[${attr}]`,$(rail)).forEach(b=>{const m=b.getAttribute(attr);b.classList.toggle("is-selected",set.has(m));b.classList.toggle("is-focused",m===focus)});const [title,text]=MODE_DESCRIPTIONS[focus];const desc=$(online?"#onlineModeDescription":"#modeDescription");if(desc)desc.innerHTML=`<strong>${title}</strong><p>${text}</p>`;const multi=set.size>1;if(!online){$("#multiModeNotice")?.classList.toggle("is-hidden",!multi);$("#roundProgramChangeRow")?.classList.toggle("is-hidden",!multi);}else $("#onlineRoundProgramChangeRow")?.classList.toggle("is-hidden",!multi);updateBoardConfigUI(online);}
function bindSwipeRail(selector,online=false){const rail=$(selector);if(!rail)return;let startX=0;rail.addEventListener("pointerdown",e=>{startX=e.clientX});rail.addEventListener("pointerup",e=>{const dx=e.clientX-startX;if(Math.abs(dx)<35)return;const focus=online?state.onlineFocusedMode:state.focusedMode,ix=MODES.indexOf(focus),next=Math.max(0,Math.min(MODES.length-1,ix+(dx<0?1:-1)));if(online)state.onlineFocusedMode=MODES[next];else state.focusedMode=MODES[next];renderModeRail(online);rail.querySelector(`[${online?"data-online-mode":"data-mode"}="${MODES[next]}"]`)?.scrollIntoView({behavior:"smooth",inline:"center",block:"nearest"});});}
