function renderSeriesResult(){const s=state.series,rows=new Map();for(const round of s.results)for(const r of round.results){const key=r.userTrackingId||r.id;if(!rows.has(key))rows.set(key,{id:key,name:r.name,color:r.color,ranks:[]});rows.get(key).ranks.push(r.rank);}const list=[...rows.values()].map(x=>({...x,average:x.ranks.reduce((a,b)=>a+b,0)/x.ranks.length})).sort((a,b)=>a.average-b.average);let rank=0,prev=null;list.forEach((x,i)=>{if(prev===null||Math.abs(x.average-prev)>1e-9)rank=i+1;x.rank=rank;prev=x.average});const mine=list.find(x=>x.id===state.user?.userTrackingId)||list[0];$("#resultRank").textContent=mine?String(mine.rank).padStart(2,"0"):"--";$("#resultTitle").textContent="総合結果";$("#resultRows").innerHTML=list.map(x=>`<div class="result-row series-row"><span class="place">${String(x.rank).padStart(2,"0")}</span><strong>${esc(x.name)}</strong><span>平均 ${x.average.toFixed(2)}位</span></div>`).join("")+`<div class="series-round-results">${s.results.map((round,i)=>`<details><summary>第${i+1}戦 ${MODE_LABELS[round.mode]}</summary>${round.results.map(r=>`<div>${r.rank}位 ${esc(r.name)} — ${esc(r.metric||r.score||"")}</div>`).join("")}</details>`).join("")}</div>`;showViewNoReset("result");}
