function resetBattleSetup(){$("#battleLive")?.classList.add("is-hidden");$(".battle-kind-switch")?.classList.remove("is-hidden");setBattleKind(state.battleKind);if(state.battleKind==="npc")goBattleStep(1);renderModeRail(false);}

function setBattleKind(kind){state.battleKind=kind==="online"?"online":"npc";$("#npcBattleTab").classList.toggle("is-active",state.battleKind==="npc");$("#onlineBattleTab").classList.toggle("is-active",state.battleKind==="online");$("#battleSetup").classList.toggle("is-hidden",state.battleKind!=="npc");$("#onlineSetup").classList.toggle("is-hidden",state.battleKind!=="online");if(state.battleKind==="online")renderOnlineArea();}
function connectOnline(){
  if(!state.user?.userTrackingId||typeof window.io!=="function")return;
  disconnectOnline();
  const socket=io({auth:{userTrackingId:state.user.userTrackingId,username:state.user.username}});state.socket=socket;
  socket.on("connect",()=>refreshRooms());
  socket.on("now:rooms-changed",()=>{if(!state.onlineRoom)refreshRooms()});
  socket.on("now:room-state",room=>{state.onlineRoom=room;renderOnlineArea()});
  socket.on("now:room-closed",()=>{state.onlineRoom=null;renderOnlineArea();toast("ルームが終了しました")});
  socket.on("now:match-start",config=>{
    document.querySelectorAll(".round-program-picker,.online-round-wait").forEach(n=>n.remove());state.onlineRoom=null;
    const launch=()=>startBattle(config,false);
    if(config.online?.series&&Number(config.online.roundIndex)>0)showRoundReveal(config.mode,Number(config.online.roundIndex)+1,Number(config.online.totalRounds)||1,launch,{shape:config.boardShape||"square",sizeKey:config.boardSizeKey||"large"});else launch();
  });
  socket.on("now:round-prepare",payload=>showOnlineRoundPrepare(payload));
  socket.on("now:series-finished",()=>renderOnlineSeriesResult());
}
function disconnectOnline(){state.socket?.disconnect();state.socket=null;state.onlineRoom=null;}
function emitSocket(event,payload={}){return new Promise((resolve,reject)=>{if(!state.socket?.connected)return reject(new Error("socket_disconnected"));const timer=setTimeout(()=>reject(new Error("socket_timeout")),7000);state.socket.emit(event,payload,(res={})=>{clearTimeout(timer);res.ok===false?reject(new Error(res.error||"socket_error")):resolve(res)});});}
async function refreshRooms(){if(!state.socket?.connected)return;try{const d=await emitSocket("now:list-rooms");state.publicRooms=d.rooms||[];renderPublicRooms();}catch{}}
function renderPublicRooms(){const host=$("#publicRoomList");if(!host)return;host.innerHTML="";if(!state.publicRooms.length){host.className="public-room-list empty-state";host.textContent="現在、募集中の公開ルームはありません。";return;}host.className="public-room-list";state.publicRooms.forEach(r=>{const b=document.createElement("button");b.className="public-room-card";const modes=r.modes||[r.mode||"territory"],board=r.boardShape?boardChoiceLabel(r.boardShape,r.boardSizeKey):`${r.size}×${r.size}`;b.innerHTML=`<span class="room-live-dot"></span><div><strong>${esc(r.hostName||"ルーム")}</strong><small>${modes.map(m=>MODE_LABELS[m]).join(" / ")} ・ ${esc(board)} ・ ${r.currentPlayers}/${r.playerCount}人</small></div><b>${r.roomId}</b>`;b.onclick=()=>joinRoom(r.roomId);host.append(b);});}
function renderOnlineArea(){const room=state.onlineRoom;$("#onlineLanding")?.classList.toggle("is-hidden",Boolean(room));$("#createRoomPanel")?.classList.add("is-hidden");$("#joinRoomPanel")?.classList.add("is-hidden");$("#onlineLobbyPanel")?.classList.toggle("is-hidden",!room);if(!room)return;$("#lobbyRoomId").textContent=room.roomId;$("#lobbyPrivacy").textContent=room.privateRoom?"プライベート":"公開";$("#lobbyRuleSummary").innerHTML=`<span>${(room.settings.modes||[room.settings.mode]).map(m=>MODE_LABELS[m]).join(" / ")}</span><span>${esc(boardChoiceLabel(room.settings.boardShape||"square",room.settings.boardSizeKey||"large"))}${room.settings.rerollBoardEachRound?" ・ 各ラウンド再抽選":""}</span><span>定員 ${room.settings.playerCount}人</span>`;const members=$("#lobbyMembers");members.innerHTML="";room.members.forEach((m,i)=>{const d=document.createElement("div");d.className=`lobby-member-slot${m.ready?" is-ready":""}`;d.innerHTML=`<span class="member-index">${String(i+1).padStart(2,"0")}</span><div><strong>${esc(m.username)}${m.role==="host"?" ・ 主":""}</strong><small>${m.programName?esc(m.programName):"駒を選択中"}</small></div><b>${m.ready?"準備OK":"待機中"}</b>`;members.append(d)});renderOnlineProgramSelect();const self=room.members.find(m=>m.isSelf);$("#onlineReadyButton").textContent=self?.ready?"準備を解除":"準備OK";$("#hostStartButton").classList.toggle("is-hidden",!room.hostIsSelf);}
function renderOnlineProgramSelect(){const s=$("#onlineProgramSelect");if(!s)return;const cur=s.value;s.innerHTML="";state.programs.forEach(p=>s.add(new Option(p.name,p.programId)));s.value=cur||state.selectedProgramId||state.programs[0]?.programId||"";}
function openOnlinePanel(kind){$("#onlineLanding").classList.add("is-hidden");$("#createRoomPanel").classList.toggle("is-hidden",kind!=="create");$("#joinRoomPanel").classList.toggle("is-hidden",kind!=="join");if(kind==="join")refreshRooms();}
async function createRoom(){try{const choice=boardChoiceFromControls(true),d=await emitSocket("now:create-room",{privateRoom:$("#privateRoom").checked,settings:{modes:selectedModeArray(true),allowRoundProgramChange:$("#onlineAllowRoundProgramChange").checked,playerCount:Number($("#onlinePlayerCount").value),boardShape:choice.shape,boardSizeKey:choice.sizeKey,rerollBoardEachRound:$("#onlineRerollBoardEachRound").checked,seed:$("#onlineSeed").value.trim(),fillWithNpc:$("#fillWithNpc").checked,npcDifficulty:$("#onlineNpcDifficulty").value}});state.onlineRoom=d.room;renderOnlineArea();}catch(e){console.error(e);toast("ルーム作成に失敗しました")}}
